// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

interface ISavingsContractV2 {
    function depositSavings(uint256 _amount) external returns (uint256 creditsIssued);
    function depositSavings(uint256 _amount, address _beneficiary) external returns (uint256 creditsIssued);
    function underlying() external view returns (address underlyingMasset);
    function exchangeRate() external view returns (uint256);
}

contract InvMutTest is Test {
    C c;
    __InvMutHandleStub stub;

    function setUp() public {
        stub = new __InvMutHandleStub();
        c = new C(ISavingsContractV2(address(stub)));
    }

    function testFuzz_property(uint256 a1, uint256 a2, address actor1, address actor2, address to) public {
        a1 = bound(a1, 1, 1e30);
        a2 = bound(a2, 0, 1e30);
        vm.assume(to != address(0) && to != address(c) && to != address(stub));
        vm.assume(actor1 != address(0) && actor2 != address(0));

        // first independent depositor supplies a1 on behalf of `to`
        vm.prank(actor1);
        c.supplyTokenTo(a1, to);

        // a second, independent depositor supplies a2 on behalf of the SAME recipient
        vm.prank(actor2);
        c.supplyTokenTo(a2, to);

        // GENERAL RULE: every deposit must ACCUMULATE: the recipient's credits
        // equal the total of all amounts supplied on their behalf (stub issues
        // credits == amount), regardless of who the depositors were.
        // The mutant wipes prior credits, so it breaks this whenever a1 > 0.
        assertTrue(c.imBalances(to) == a1 + a2);
    }
}

contract __InvMutHandleStub {
    function factory() external view returns (address) { return address(this); }
    function createPair(address, address) external view returns (address) { return address(this); }
    function underlying() external view returns (address) { return address(this); }
    function WETH() external view returns (address) { return address(this); }
    function name() external pure returns (string memory) { return "S"; }
    function symbol() external pure returns (string memory) { return "S"; }
    function decimals() external pure returns (uint8) { return 18; }
    function totalSupply() external pure returns (uint256) { return 0; }
    function balanceOf(address) external pure returns (uint256) { return 0; }
    function allowance(address, address) external pure returns (uint256) { return type(uint256).max; }
    function approve(address, uint256) external pure returns (bool) { return true; }
    function transfer(address, uint256) external pure returns (bool) { return true; }
    function transferFrom(address, address, uint256) external pure returns (bool) { return true; }
    function depositSavings(uint256 amount) external payable returns (uint256) { return amount; }
    function depositSavings(uint256 amount, address) external payable returns (uint256) { return amount; }
    function exchangeRate() external pure returns (uint256) { return 1e18; }
    receive() external payable {}
    fallback() external payable {}
}
